    pg.innerHTML=(p?`<button data-go="${p.id}"><small>← Previous</small><span>${amp(p.t)}</span></button>`:'')+(n?`<button class="next" data-go="${n.id}"><small>Next →</small><span>${amp(n.t)}</span></button>`:'');
