  function lpOf(t){const p=phaseOf(RH_STEPS,t),a=RH_STEPS[p].from,b=p<RH_STEPS.length-1?RH_STEPS[p+1].from:1.0001;return ramp(t,a,Math.max(a+.01,RH_STEPS[p].at))}
